const INDEX_HTML = "<!doctype html>\n<html lang=\"fr\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#16131c\">\n  <title>Philosophes — Top Trumps</title>\n  <style>:root{--ink:#17131d;--paper:#f4ead4;--gold:#c9973b;--violet:#5f4c88;--line:#2b2434;--muted:#756c7d;--panel:#231c2b}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 20% 10%,#443555 0,#18141d 42%,#0d0b10 100%);color:#f8f2e7;font-family:ui-rounded,\"Avenir Next\",system-ui,sans-serif;min-height:100vh}button,input,select{font:inherit}button{cursor:pointer;border:1px solid #75678a;border-radius:14px;padding:13px 17px;background:#2b2234;color:#fff;font-weight:800;letter-spacing:.03em}.primary{background:linear-gradient(135deg,#d6a54b,#9c6d29);border-color:#e8c875;color:#18120a}.ghost{background:transparent}.compact{padding:8px 12px;font-size:.78rem}.hidden{display:none!important}.screen{display:none;min-height:100vh;padding:28px 20px}.screen.active{display:flex}.hero{flex-direction:column;align-items:center;justify-content:center;text-align:center}.brand{font-family:Georgia,serif;font-size:clamp(3.2rem,12vw,7rem);font-weight:900;letter-spacing:-.05em;color:#f1d59c;text-shadow:0 3px 0 #664720}.subtitle{letter-spacing:.42em;margin:8px 0 18px;color:#d3a85a}.tagline{max-width:720px;color:#cfc5d4}.actions{display:grid;gap:12px;width:min(440px,100%);margin-top:24px}.panel{margin:auto;align-self:center;flex-direction:column;gap:16px;width:min(520px,100%);min-height:auto;background:rgba(35,28,43,.94);border:1px solid #6f5c7b;border-radius:28px;padding:26px;box-shadow:0 24px 60px #0008}.wide{width:min(680px,100%)}label{display:grid;gap:7px;color:#d8cfe0;font-weight:700}input,select{width:100%;padding:13px;border-radius:12px;border:1px solid #6d5c78;background:#151119;color:#fff}.code-input{text-transform:uppercase;letter-spacing:.28em;text-align:center;font-size:1.35rem}.eyebrow{font-size:.72rem;letter-spacing:.2em;color:#b89dca}.room-code{font-size:3rem;font-weight:900;letter-spacing:.16em;color:#f0cf8d}.player-list{display:grid;gap:9px}.player-row,.score-chip{display:flex;justify-content:space-between;gap:10px;padding:11px 13px;background:#18131d;border-radius:12px;border:1px solid #44384c}.muted{color:#aaa0b0}.game-screen{display:none!important;flex-direction:column;gap:12px}.game-screen.active{display:flex!important}.gamebar{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;background:#17121b;border:1px solid #493d52;border-radius:14px;padding:11px 14px}.scoreboard{display:flex;gap:8px;overflow:auto;padding-bottom:2px}.score-chip{white-space:nowrap}.score-chip.me{border-color:#d8ac58}.gamegrid{display:grid;grid-template-columns:minmax(0,560px) minmax(300px,1fr);gap:18px;align-items:start}.philo-card{background:var(--paper);color:var(--ink);border:8px solid #b98c3c;border-radius:24px;overflow:hidden;box-shadow:0 20px 50px #0008}.portrait{height:250px;background:linear-gradient(135deg,#d6c1a0,#7b6490);position:relative;border-bottom:4px solid #31273a}.portrait img{width:100%;height:100%;object-fit:cover;display:block}.portrait-placeholder{height:100%;display:none;place-items:center;text-align:center;font-size:1.15rem;font-weight:900;letter-spacing:.08em;color:#211c27}.portrait img[style*=\"display: none\"]+.portrait-placeholder{display:grid}.card-head{display:flex;justify-content:space-between;gap:16px;padding:15px 17px 9px}.card-head h1{font-family:Georgia,serif;margin:0;font-size:2rem}.card-head p{margin:3px 0;color:#6c626e}.current{align-self:start;background:#5f4c88;color:#fff;padding:7px 10px;border-radius:10px;font-size:.78rem}.facts{display:grid;gap:4px;padding:0 17px 10px;color:#615767;font-size:.9rem}.philo-card blockquote{margin:4px 17px 14px;padding:12px 14px;border-left:4px solid #a6782c;background:#efe1c4;font-family:Georgia,serif}.philo-card blockquote small{display:block;margin-top:8px;color:#716572;font-family:system-ui}.stats{border-top:2px solid #3e3542}.stat{display:grid;grid-template-columns:130px 1fr 55px;gap:10px;align-items:center;padding:10px 13px;border-bottom:1px solid #cabb9e}.stat:nth-child(odd){background:#f0e3cb}.stat span{font-size:.78rem;line-height:1.25;color:#584e5e}.stat strong{font-size:1.55rem;text-align:center}.masked{filter:blur(7px);user-select:none}.playpanel{background:rgba(30,24,36,.95);border:1px solid #4e4058;border-radius:22px;padding:18px;position:sticky;top:12px}.phase{font-size:1.08rem}.category-buttons{display:grid;gap:10px}.cat-btn{display:grid;grid-template-columns:1fr auto;gap:4px 12px;text-align:left}.cat-btn span{grid-column:1;font-size:.8rem;color:#d7cde0;font-weight:500}.cat-btn em{grid-column:2;grid-row:1/3;align-self:center;font-size:1.5rem;font-style:normal;color:#f1cc83}.cat-btn:disabled{opacity:.48}.reveal-grid{display:grid;gap:10px}.reveal-card{display:grid;grid-template-columns:1fr auto;gap:3px 10px;padding:12px;background:#17121b;border:1px solid #4a3d54;border-radius:12px}.reveal-card span{font-size:.8rem;color:#aaa0b0}.reveal-card strong{grid-column:2;grid-row:1/3;font-size:2rem}.reveal-card.winner{border-color:#d1a34c;box-shadow:inset 0 0 0 1px #d1a34c}.leave{align-self:flex-end}dialog{max-width:560px;border:1px solid #7f6a8c;border-radius:20px;background:#211a28;color:#fff;padding:24px}dialog::backdrop{background:#000b}@media(max-width:850px){.gamegrid{grid-template-columns:1fr}.playpanel{position:static}.portrait{height:210px}.stat{grid-template-columns:105px 1fr 45px}.screen{padding:14px 10px}.philo-card{border-width:5px}}\n</style>\n</head>\n<body>\n  <main>\n    <section id=\"home\" class=\"screen active hero\">\n      <div class=\"brand\">PHILOSOPHES</div>\n      <div class=\"subtitle\">TOP TRUMPS</div>\n      <p class=\"tagline\">Notoriété · Aventure · Rationalité · Radicalité · Impact socio-culturel</p>\n      <div class=\"actions\">\n        <button id=\"createBtn\" class=\"primary\">CRÉER UNE PARTIE</button>\n        <button id=\"joinBtn\">REJOINDRE UNE PARTIE</button>\n        <button id=\"rulesBtn\" class=\"ghost\">RÈGLES</button>\n      </div>\n    </section>\n\n    <section id=\"create\" class=\"screen panel\">\n      <h1>Créer une partie</h1>\n      <label>Votre nom<input id=\"hostName\" maxlength=\"24\" placeholder=\"Socrate\"></label>\n      <label>Mode<select id=\"gameMode\"><option value=\"classic\">Classique</option><option value=\"blind\">À l’aveugle</option></select></label>\n      <label>Joueurs<select id=\"maxPlayers\"><option>2</option><option>3</option><option selected>4</option><option>5</option><option>6</option></select></label>\n      <button id=\"confirmCreate\" class=\"primary\">CRÉER LA SALLE</button>\n      <button data-screen=\"home\" class=\"ghost\">RETOUR</button>\n    </section>\n\n    <section id=\"join\" class=\"screen panel\">\n      <h1>Rejoindre</h1>\n      <label>Votre nom<input id=\"joinName\" maxlength=\"24\" placeholder=\"Diogène\"></label>\n      <label>Code de salle<input id=\"roomCodeInput\" maxlength=\"6\" class=\"code-input\" placeholder=\"ABC123\"></label>\n      <button id=\"confirmJoin\" class=\"primary\">REJOINDRE</button>\n      <button data-screen=\"home\" class=\"ghost\">RETOUR</button>\n    </section>\n\n    <section id=\"lobby\" class=\"screen panel wide\">\n      <div class=\"eyebrow\">CODE DE LA SALLE</div><div id=\"roomCode\" class=\"room-code\">—</div>\n      <button id=\"copyCode\" class=\"ghost compact\">COPIER LE CODE</button>\n      <p id=\"modeLabel\"></p><div id=\"playerList\" class=\"player-list\"></div><p id=\"lobbyStatus\" class=\"muted\"></p>\n      <button id=\"startOnlineGame\" class=\"primary hidden\">LANCER LA PARTIE</button>\n      <button id=\"leaveLobby\" class=\"ghost\">QUITTER</button>\n    </section>\n\n    <section id=\"game\" class=\"screen game-screen\">\n      <header class=\"gamebar\"><span id=\"turnLabel\"></span><strong id=\"leaderLabel\"></strong><span id=\"potLabel\"></span></header>\n      <div id=\"scoreboard\" class=\"scoreboard\"></div>\n      <div class=\"gamegrid\">\n        <article id=\"myCard\" class=\"philo-card\"></article>\n        <aside class=\"playpanel\">\n          <p id=\"phaseMessage\" class=\"phase\"></p>\n          <div id=\"waitingChoice\"><div id=\"categoryButtons\" class=\"category-buttons\"></div></div>\n          <div id=\"revealBox\" class=\"hidden\"><h2 id=\"revealTitle\"></h2><div id=\"revealGrid\" class=\"reveal-grid\"></div><p id=\"roundResult\"></p><button id=\"nextRound\" class=\"primary hidden\">SUIVANT</button></div>\n        </aside>\n      </div>\n      <button id=\"leaveGame\" class=\"ghost compact leave\">QUITTER</button>\n    </section>\n\n    <section id=\"winner\" class=\"screen panel\"><div class=\"eyebrow\">VICTOIRE</div><h1 id=\"winnerName\">—</h1><button id=\"winnerHome\" class=\"primary\">RETOUR À L’ACCUEIL</button></section>\n  </main>\n\n  <dialog id=\"rulesDialog\"><h2>Règles</h2><p>Le leader choisit une catégorie sur sa carte. Tous les joueurs révèlent alors le score correspondant. Le meilleur score remporte le pli et devient leader.</p><p>En mode à l’aveugle, les scores sont cachés avant le choix, mais les commentaires, faits et illustrations restent visibles.</p><p>En cas d’égalité, les cartes restent dans une cagnotte et seuls les joueurs à égalité rejouent pour la remporter.</p><button id=\"closeRules\" class=\"primary\">FERMER</button></dialog>\n  <script src=\"/socket.io/socket.io.js\"></script><script>(() => {\nlet CATS=[]; const socket=io(); let state=null;\nlet identity=JSON.parse(localStorage.getItem('philoIdentityV2')||'null');\nconst $=id=>document.getElementById(id); const esc=s=>String(s??'').replace(/[&<>'\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',\"'\":'&#39;','\"':'&quot;'}[c]));\nfunction show(id){document.querySelectorAll('.screen').forEach(x=>x.classList.remove('active'));$(id).classList.add('active');}\nfunction slugId(c){return c?.ID||'';}\nfunction portrait(c){return `<div class=\"portrait\"><img src=\"${esc(c.portrait)}\" alt=\"\" onerror=\"this.style.display='none';this.nextElementSibling.style.display='grid'\"><div class=\"portrait-placeholder\">ILLUSTRATION<br>À AJOUTER<br><small>#${slugId(c)}</small></div></div>`;}\n$('rulesBtn').onclick=()=>$('rulesDialog').showModal(); $('closeRules').onclick=()=>$('rulesDialog').close();\ndocument.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>show(b.dataset.screen)); $('createBtn').onclick=()=>show('create'); $('joinBtn').onclick=()=>show('join');\n$('confirmCreate').onclick=()=>socket.emit('createRoom',{name:$('hostName').value,mode:$('gameMode').value,maxPlayers:+$('maxPlayers').value});\n$('confirmJoin').onclick=()=>socket.emit('joinRoom',{code:$('roomCodeInput').value,name:$('joinName').value});\nsocket.on('identity',x=>{identity=x;localStorage.setItem('philoIdentityV2',JSON.stringify(x));});\nsocket.on('errorMessage',m=>alert(m)); if(identity) socket.emit('reconnectRoom',identity);\nsocket.on('state',s=>{state=s;CATS=s.config?.categories||CATS;render();});\nfunction render(){if(!state)return;if(state.status==='lobby'){show('lobby');renderLobby();}else if(state.status==='playing'){show('game');renderGame();}else if(state.status==='finished'){const w=state.players.find(p=>p.id===state.winnerId);$('winnerName').textContent=w?.name||'—';show('winner');}}\nfunction renderLobby(){ $('roomCode').textContent=state.code; $('modeLabel').textContent=state.mode==='blind'?'Mode à l’aveugle':'Mode classique'; $('playerList').innerHTML=state.players.map(p=>`<div class=\"player-row\"><b>${esc(p.name)}</b><span>${p.isHost?'Hôte':''}${p.id===state.me.id?' · Vous':''}</span></div>`).join(''); $('lobbyStatus').textContent=state.canStart?`${state.players.length} joueurs prêts.`:(state.me.id===state.players.find(p=>p.isHost)?.id?'En attente d’au moins un autre joueur…':'En attente du lancement par l’hôte…'); $('startOnlineGame').classList.toggle('hidden',!state.canStart); }\n$('copyCode').onclick=async()=>{await navigator.clipboard?.writeText(state?.code||'');$('copyCode').textContent='COPIÉ !';setTimeout(()=>$('copyCode').textContent='COPIER LE CODE',1000)}; $('startOnlineGame').onclick=()=>socket.emit('startGame');\nfunction renderGame(){ $('turnLabel').textContent='Tour '+state.round; const leader=state.players.find(p=>p.id===state.leaderId); $('leaderLabel').textContent='Leader : '+(leader?.name||'—'); $('potLabel').textContent='Cagnotte : '+state.potCount; $('scoreboard').innerHTML=state.players.map(p=>`<div class=\"score-chip ${p.id===state.me.id?'me':''}\">${esc(p.name)} · ${p.cardCount}${p.connected?'':' · hors ligne'}</div>`).join(''); $('myCard').innerHTML=state.me.card?cardHtml(state.me.card):'<div class=\"portrait-placeholder\">Vous n’avez plus de cartes.</div>';\nif(state.phase==='choose'){ $('waitingChoice').classList.remove('hidden'); $('revealBox').classList.add('hidden'); $('phaseMessage').textContent=state.canChoose?'À vous de choisir la catégorie.':`En attente du choix de ${leader?.name||'leader'}…`; $('categoryButtons').innerHTML=CATS.map(cat=>`<button class=\"cat-btn\" data-cat=\"${esc(cat)}\" ${state.canChoose?'':'disabled'}><b>${esc(cat)}</b><span>${esc(state.me.card?.['Commentaire '+cat]||'')}</span><em>${state.me.card?.[cat]==null?'?':state.me.card?.[cat]}</em></button>`).join(''); document.querySelectorAll('.cat-btn').forEach(b=>b.onclick=()=>socket.emit('chooseCategory',b.dataset.cat)); } else { $('waitingChoice').classList.add('hidden'); $('revealBox').classList.remove('hidden'); renderReveal(); } }\nfunction cardHtml(c){return `${portrait(c)}<div class=\"card-head\"><div><h1>${esc(c.Philosophe)}</h1><p>${esc(c.Dates)}</p></div><div class=\"current\">${esc(c.Courant)}</div></div><div class=\"facts\"><span>${esc(c.Pays)}</span><span>${esc(c['Œuvres'])}</span></div><blockquote>« ${esc(c.Citation)} »<small>${esc(c['Source citation'])}</small></blockquote><div class=\"stats\">${CATS.map(cat=>`<div class=\"stat\"><b>${esc(cat)}</b><span>${esc(c['Commentaire '+cat]||'')}</span><strong class=\"${c[cat]==null?'masked':''}\">${c[cat]==null?'?':c[cat]}</strong></div>`).join('')}</div>`;}\nfunction renderReveal(){const r=state.reveal;if(!r)return;$('revealTitle').textContent=r.category;$('phaseMessage').textContent='Les scores sont révélés.';$('revealGrid').innerHTML=r.entries.map(e=>{const p=state.players.find(x=>x.id===e.pid);return `<div class=\"reveal-card ${r.winners.includes(e.pid)?'winner':''}\"><b>${esc(p?.name||'')}</b><span>${esc(e.philosopher)}</span><strong>${e.score}</strong></div>`}).join('');$('roundResult').textContent=r.winners.length===1?`${state.players.find(p=>p.id===r.winners[0])?.name||''} remporte le pli.`:`Égalité entre ${r.winners.map(id=>state.players.find(p=>p.id===id)?.name).join(', ')}.`;$('nextRound').classList.toggle('hidden',!state.canAdvance);$('nextRound').textContent=r.winners.length===1?'ATTRIBUER LE PLI':'CONTINUER L’ÉGALITÉ';}\n$('nextRound').onclick=()=>socket.emit('nextRound');\nfunction leave(){socket.emit('leaveRoom');localStorage.removeItem('philoIdentityV2');identity=null;state=null;show('home');}\n$('leaveLobby').onclick=leave;$('leaveGame').onclick=leave;$('winnerHome').onclick=leave;\n})();\n</script>\n</body></html>\n";
app.get('/', (_req, res) => res.type('html').send(INDEX_HTML));
app.get('/api/config', (_req, res) => res.json({ ...game, cardCount: cards.length }));

const CATEGORIES = game.categories;
const rooms = new Map();
const cardById = new Map(cards.map(c => [c.ID, c]));
const rand = n => crypto.randomBytes(n).toString('hex');
const safeName = s => String(s || '').trim().slice(0, 24) || 'Joueur';
const shuffle = source => {
  const a = [...source];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
};
function roomCode() {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let s;
  do s = Array.from({ length: 6 }, () => chars[Math.floor(Math.random() * chars.length)]).join('');
  while (rooms.has(s));
  return s;
}
function portraitPath(card) {
  if (!card) return null;
  return null;
}
function publicCard(c, masked = false) {
  if (!c) return null;
  const out = {
    ID: c.ID, Philosophe: c.Philosophe, Dates: c.Dates, Pays: c.Pays, Courant: c.Courant,
    Citation: c.Citation, 'Source citation': c['Source citation'], 'Œuvres': c['Œuvres'],
    portrait: portraitPath(c)
  };
  for (const cat of CATEGORIES) {
    out['Commentaire ' + cat] = c['Commentaire ' + cat];
    out[cat] = masked ? null : c[cat];
  }
  return out;
}
function participants(room) {
  if (room.tiePlayers.length) return room.tiePlayers.filter(id => room.players.get(id)?.deck.length);
  return [...room.players.values()].filter(p => p.deck.length).map(p => p.id);
}
function revealData(room) {
  const entries = Object.entries(room.currentCards).map(([pid, cid]) => ({
    pid, cid, score: cardById.get(cid)?.[room.selectedCategory] ?? -Infinity,
    philosopher: cardById.get(cid)?.Philosophe || ''
  }));
  if (!entries.length) return null;
  const max = Math.max(...entries.map(x => x.score));
  return { category: room.selectedCategory, entries, winners: entries.filter(x => x.score === max).map(x => x.pid) };
}
function playerView(room, pid) {
  const p = room.players.get(pid);
  if (!p) return null;
  const top = cardById.get(p.deck[0]);
  const masked = room.mode === 'blind' && room.phase === 'choose' && game.blindMode.hideScoresUntilCategoryChosen;
  return {
    config: { title: game.title, categories: CATEGORIES },
    code: room.code, mode: room.mode, maxPlayers: room.maxPlayers, status: room.status,
    round: room.round, phase: room.phase, leaderId: room.leaderId, selectedCategory: room.selectedCategory,
    potCount: room.pot.length,
    me: { id: p.id, name: p.name, cardCount: p.deck.length, card: publicCard(top, masked) },
    players: [...room.players.values()].map(x => ({ id: x.id, name: x.name, cardCount: x.deck.length, connected: x.connected, isHost: x.id === room.hostId })),
    canStart: p.id === room.hostId && room.status === 'lobby' && room.players.size >= game.minPlayers,
    canChoose: p.id === room.leaderId && room.phase === 'choose' && participants(room).includes(p.id),
    canAdvance: p.id === room.hostId && room.phase === 'reveal',
    participants: participants(room), reveal: room.phase === 'reveal' ? revealData(room) : null,
    winnerId: room.winnerId
  };
}
function emitRoom(room) {
  for (const p of room.players.values()) if (p.socketId) io.to(p.socketId).emit('state', playerView(room, p.id));
}
function findPlayerByToken(room, token) { return [...room.players.values()].find(p => p.token === token); }
function fail(socket, msg) { socket.emit('errorMessage', msg); }

io.on('connection', socket => {
  socket.on('createRoom', ({ name, mode, maxPlayers }) => {
    const code = roomCode(), id = rand(8), token = rand(16);
    const room = {
      code,
      mode: mode === 'blind' ? 'blind' : 'classic',
      maxPlayers: Math.min(game.maxPlayers, Math.max(game.minPlayers, +maxPlayers || 4)),
      hostId: id, status: 'lobby', round: 0, phase: 'lobby', leaderId: id,
      selectedCategory: null, currentCards: {}, pot: [], tiePlayers: [], winnerId: null, players: new Map()
    };
    room.players.set(id, { id, token, name: safeName(name), socketId: socket.id, connected: true, deck: [] });
    rooms.set(code, room);
    socket.join(code); socket.data.room = code; socket.data.player = id;
    socket.emit('identity', { code, playerId: id, token });
    emitRoom(room);
  });

  socket.on('joinRoom', ({ code, name }) => {
    code = String(code || '').trim().toUpperCase();
    const room = rooms.get(code);
    if (!room) return fail(socket, 'Salle introuvable.');
    if (room.status !== 'lobby') return fail(socket, 'La partie a déjà commencé.');
    if (room.players.size >= room.maxPlayers) return fail(socket, 'La salle est complète.');
    const id = rand(8), token = rand(16);
    room.players.set(id, { id, token, name: safeName(name), socketId: socket.id, connected: true, deck: [] });
    socket.join(code); socket.data.room = code; socket.data.player = id;
    socket.emit('identity', { code, playerId: id, token });
    emitRoom(room);
  });

  socket.on('reconnectRoom', ({ code, token }) => {
    const room = rooms.get(String(code || '').toUpperCase());
    if (!room) return fail(socket, 'La partie n’existe plus.');
    const p = findPlayerByToken(room, token);
    if (!p) return fail(socket, 'Impossible de vous reconnecter à cette partie.');
    p.socketId = socket.id; p.connected = true;
    socket.join(room.code); socket.data.room = room.code; socket.data.player = p.id;
    socket.emit('identity', { code: room.code, playerId: p.id, token: p.token });
    emitRoom(room);
  });

  socket.on('startGame', () => {
    const room = rooms.get(socket.data.room);
    if (!room || socket.data.player !== room.hostId || room.status !== 'lobby' || room.players.size < game.minPlayers) return;
    const ps = [...room.players.values()];
    const deck = shuffle(cards.map(c => c.ID));
    ps.forEach(p => p.deck = []);
    deck.forEach((cid, i) => ps[i % ps.length].deck.push(cid));
    room.status = 'playing'; room.round = 1; room.phase = 'choose'; room.leaderId = ps[0].id;
    room.pot = []; room.tiePlayers = []; room.currentCards = {}; room.selectedCategory = null;
    emitRoom(room);
  });

  socket.on('chooseCategory', cat => {
    const room = rooms.get(socket.data.room);
    if (!room || room.status !== 'playing' || room.phase !== 'choose' || socket.data.player !== room.leaderId || !CATEGORIES.includes(cat)) return;
    const ids = participants(room), curr = {};
    for (const pid of ids) {
      const p = room.players.get(pid);
      if (p?.deck.length) curr[pid] = p.deck[0];
    }
    if (Object.keys(curr).length < 2) return;
    room.selectedCategory = cat; room.currentCards = curr; room.phase = 'reveal';
    emitRoom(room);
  });

  socket.on('nextRound', () => {
    const room = rooms.get(socket.data.room);
    if (!room || socket.data.player !== room.hostId || room.phase !== 'reveal') return;
    const info = revealData(room); if (!info) return;
    const played = [];
    for (const [pid, cid] of Object.entries(room.currentCards)) {
      const p = room.players.get(pid);
      if (p?.deck[0] === cid) p.deck.shift();
      played.push(cid);
    }
    room.pot.push(...played);
    if (info.winners.length > 1 && game.ties.usePot) {
      const tied = info.winners.filter(pid => room.players.get(pid)?.deck.length);
      if (tied.length >= 2) {
        room.tiePlayers = tied; room.leaderId = tied[0]; room.round++; room.phase = 'choose';
        room.currentCards = {}; room.selectedCategory = null; emitRoom(room); return;
      }
      if (tied.length === 1) info.winners = [tied[0]];
    }
    const winner = info.winners[0], wp = room.players.get(winner); if (!wp) return;
    wp.deck.push(...shuffle(room.pot));
    room.pot = []; room.tiePlayers = []; room.leaderId = winner; room.round++; room.phase = 'choose';
    room.currentCards = {}; room.selectedCategory = null;
    const alive = [...room.players.values()].filter(p => p.deck.length);
    if (alive.length === 1) { room.status = 'finished'; room.winnerId = alive[0].id; room.phase = 'finished'; }
    emitRoom(room);
  });

  socket.on('leaveRoom', () => leaveSocket(socket, true));
  socket.on('disconnect', () => leaveSocket(socket, false));
});

function leaveSocket(socket, explicit) {
  const room = rooms.get(socket.data.room); if (!room) return;
  const p = room.players.get(socket.data.player); if (!p) return;
  if (room.status === 'lobby' || explicit) {
    room.players.delete(p.id);
    if (room.players.size === 0) { rooms.delete(room.code); return; }
    if (room.hostId === p.id) room.hostId = [...room.players.keys()][0];
  } else { p.connected = false; p.socketId = null; }
  emitRoom(room);
}

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => console.log(`Philosophes multijoueur : http://localhost:${PORT}`));
